<script lang="ts">
  import { onMount } from 'svelte';
  import { page } from '$app/stores';
  import { convertFileSrc, invoke } from '@tauri-apps/api/core';
  import { exportClip, exportError, exportStarted, lastExported } from '$lib/daemon';
  import { clamp, cleanRanges, editedToSource, makeHistory, nextRetainedTime, sourceToEdited, splitAt, trimRange, type AudioSetting, type EditPlan, type TimeRange } from '$lib/editor';

  interface AudioTrack { stream_index: number; name: string; channels: number; sample_rate: number; preview_path: string; waveform: number[] }
  interface ClipInfo { path: string; duration: number; width: number; height: number; video_fps: number; source_bytes: number; source_modified_ms: number; audio: AudioTrack[] }
  interface Project { version: 1; source_path: string; source_bytes: number; source_modified_ms: number; plan: EditPlan; export_fps: number }
  let info = $state<ClipInfo | null>(null); let plan = $state<EditPlan>({ ranges: [], audio: [] });
  let selected = $state(0); let sourceTime = $state(0); let playing = $state(false); let loading = $state(true); let loadError = $state(''); let error = $state(''); let saved = $state('');
  let fps = $state('60'); let customFps = $state(''); let video: HTMLVideoElement | undefined = $state(); let timeline: HTMLDivElement | undefined = $state(); let audioContext: AudioContext | null = null;
  let stemElements = $state<HTMLAudioElement[]>([]); let gainNodes: GainNode[] = []; let history = $state.raw(makeHistory<EditPlan>({ ranges: [], audio: [] })); let historyVersion = $state(0); let animationFrame: number | null = null; let loadedPath = '';
  const sourcePath = $derived($page.url.searchParams.get('path') ?? '');
  const current = () => plan.ranges[selected];
  const totalDuration = $derived(plan.ranges.reduce((sum, range) => sum + range.end - range.start, 0));
  const requestedFps = $derived(fps === 'custom' ? Number(customFps) : Number(fps));
  const validFps = $derived(Number.isSafeInteger(requestedFps) && requestedFps >= 1 && requestedFps <= 2147483647);
  const rulerTicks = $derived(info ? Array.from({ length: 6 }, (_, index) => info!.duration * index / 5) : []);
  const canUndo = $derived.by(() => { historyVersion; return history.canUndo; });
  const canRedo = $derived.by(() => { historyVersion; return history.canRedo; });
  const tc = (seconds: number) => { const ms = Math.round(Math.max(0, seconds) * 1000); const s = Math.floor(ms / 1000); return `${String(Math.floor(s / 3600)).padStart(2,'0')}:${String(Math.floor(s / 60) % 60).padStart(2,'0')}:${String(s % 60).padStart(2,'0')}.${String(ms % 1000).padStart(3,'0')}`; };
  const percent = (time: number) => info ? `${clamp(time / info.duration * 100, 0, 100)}%` : '0%';
  const trackSetting = (stream_index: number) => plan.audio.find((x) => x.stream_index === stream_index) ?? { stream_index, gain_db: 0, muted: false };
  const commit = (next: EditPlan) => { plan = { ranges: cleanRanges(next.ranges, info?.duration ?? 0), audio: next.audio }; history.push(plan); historyVersion++; selected = Math.min(selected, Math.max(0, plan.ranges.length - 1)); };
  const alterAudio = (stream_index: number, patch: Partial<AudioSetting>) => { const prior = trackSetting(stream_index); const found = plan.audio.some((item) => item.stream_index === stream_index); commit({ ...plan, audio: found ? plan.audio.map((item) => item.stream_index === stream_index ? { ...item, ...patch } : item) : [...plan.audio, { ...prior, ...patch }] }); };
  const sourceProject = (): Project => ({ version: 1, source_path: info!.path, source_bytes: info!.source_bytes, source_modified_ms: info!.source_modified_ms, plan, export_fps: validFps ? requestedFps : 60 });
  const seek = (time: number) => { sourceTime = clamp(time, 0, info?.duration ?? 0); if (video) video.currentTime = sourceTime; stemElements.forEach((stem) => stem.currentTime = sourceTime); };
  const applyGains = () => { info?.audio.forEach((track, index) => { const setting = trackSetting(track.stream_index); if (gainNodes[index]) gainNodes[index].gain.value = setting.muted ? 0 : Math.pow(10, setting.gain_db / 20); }); };
  const stopClock = () => { if (animationFrame !== null) cancelAnimationFrame(animationFrame); animationFrame = null; };
  const pause = () => { stopClock(); video?.pause(); stemElements.forEach((stem) => stem.pause()); playing = false; };
  const clock = () => { if (!playing || !video || !info) return; sourceTime = video.currentTime; const retained = nextRetainedTime(plan.ranges, sourceTime); if (retained === null) { pause(); return; } if (retained > sourceTime + 0.008) { seek(retained); } else { stemElements.forEach((stem) => { if (Math.abs(stem.currentTime - sourceTime) > 0.04) stem.currentTime = sourceTime; }); } animationFrame = requestAnimationFrame(clock); };
  const play = async () => { if (!info || !video) return; error = ''; const next = nextRetainedTime(plan.ranges, sourceTime); if (next === null) seek(plan.ranges[0]?.start ?? 0); else if (next !== sourceTime) seek(next); try { if (audioContext?.state === 'suspended') await audioContext.resume(); await Promise.all([video.play(), ...stemElements.map((stem) => stem.play())]); playing = true; stopClock(); animationFrame = requestAnimationFrame(clock); } catch (reason) { pause(); error = `Preview could not start: ${reason instanceof Error ? reason.message : String(reason)}`; } };
  const togglePlay = () => playing ? pause() : play();
  const trim = (edge: 'start' | 'end') => { if (!info) return; commit({ ...plan, ranges: trimRange(plan.ranges, selected, edge, sourceTime, info.duration) }); };
  const remove = () => { if (plan.ranges.length <= 1) return; commit({ ...plan, ranges: plan.ranges.filter((_, i) => i !== selected) }); };
  const split = () => { if (!info) return; commit({ ...plan, ranges: splitAt(plan.ranges, sourceTime, info.duration) }); };
  const reset = () => { if (!info) return; commit({ ranges: [{ start: 0, end: info.duration }], audio: info.audio.map((a) => ({ stream_index: a.stream_index, gain_db: 0, muted: false })) }); seek(0); };
  const undo = () => { plan = history.undo(); historyVersion++; selected = Math.min(selected, plan.ranges.length - 1); };
  const redo = () => { plan = history.redo(); historyVersion++; selected = Math.min(selected, plan.ranges.length - 1); };
  const saveProject = async () => { if (!info) return; try { saved = String(await invoke('save_editor_project', { path: info.path, project: sourceProject() })); } catch (reason) { error = `Could not save edits: ${reason}`; } };
  const requestExport = () => { if (!info || !validFps || $exportStarted) return; exportError.set(null); exportStarted.set({ path: '', source: info.path, fps: requestedFps, at: Date.now() }); exportClip(info.path, requestedFps, plan).catch((reason: unknown) => { exportStarted.set(null); exportError.set(String(reason)); }); };
  const timelineClick = (event: MouseEvent) => { if (!timeline || !info) return; const box = timeline.getBoundingClientRect(); seek((event.clientX - box.left) / box.width * info.duration); };
  const keydown = (event: KeyboardEvent) => { const element = event.target as HTMLElement; if (element.closest('input,select,textarea,button')) return; if (event.code === 'Space') { event.preventDefault(); togglePlay(); } else if (event.key === 'i' || event.key === 'I') trim('start'); else if (event.key === 'o' || event.key === 'O') trim('end'); else if (event.key === 'c' || event.key === 'C' || event.key === 's' || event.key === 'S') split(); else if (event.key === 'Delete') remove(); else if (event.ctrlKey && event.key.toLowerCase() === 'z') { event.preventDefault(); undo(); } else if (event.ctrlKey && event.key.toLowerCase() === 'y') { event.preventDefault(); redo(); } };
  const onVideoTime = () => { if (!playing && video) sourceTime = video.currentTime; };
  const loadEditor = async (path: string) => { pause(); audioContext?.close(); audioContext = null; gainNodes = []; stemElements = []; info = null; loadError = ''; error = ''; saved = ''; loading = true; if (!path) { loadError = 'Choose a clip from the Clips library to open the editor.'; loading = false; return; } try { const prepared = await invoke<ClipInfo>('prepare_editor', { path }); if (path !== sourcePath) return; info = prepared; const defaultPlan = { ranges: [{ start: 0, end: prepared.duration }], audio: prepared.audio.map((a) => ({ stream_index: a.stream_index, gain_db: 0, muted: false })) }; let stored: Project | null = null; try { stored = await invoke<Project | null>('load_editor_project', { path }); } catch { error = 'Saved edits could not be read. Loaded a fresh edit plan.'; } if (path !== sourcePath) return; const savedPlan = stored?.plan; plan = { ranges: savedPlan?.ranges ?? defaultPlan.ranges, audio: prepared.audio.map((track) => savedPlan?.audio.find((item) => item.stream_index === track.stream_index) ?? { stream_index: track.stream_index, gain_db: 0, muted: false }) }; const savedFps = stored?.export_fps ?? 60; if ([60, 120, 240, 480, 960].includes(savedFps)) fps = String(savedFps); else { fps = 'custom'; customFps = String(savedFps); } selected = 0; sourceTime = plan.ranges[0]?.start ?? 0; history = makeHistory(plan); historyVersion++; requestAnimationFrame(() => seek(sourceTime)); } catch (reason) { loadError = `Could not prepare this clip: ${reason}`; } finally { if (path === sourcePath) loading = false; } };
  onMount(() => { window.addEventListener('keydown', keydown); return () => { window.removeEventListener('keydown', keydown); pause(); audioContext?.close(); }; });
  $effect(() => { const path = sourcePath; if (path !== loadedPath || (!path && loading)) { loadedPath = path; void loadEditor(path); } });
  $effect(() => { if (info && stemElements.length === info.audio.length && !audioContext) { audioContext = new AudioContext(); gainNodes = stemElements.map((stem) => { const gain = audioContext!.createGain(); audioContext!.createMediaElementSource(stem).connect(gain).connect(audioContext!.destination); return gain; }); applyGains(); } });
  $effect(() => { plan; applyGains(); });
</script>

<svelte:head><title>Recall Hub — Clip editor</title></svelte:head>

<div class="editor-head"><div class="crumb"><a href="/">Clips</a><span>/</span><h1 title={info?.path}>{info ? info.path.split('\\').pop() : 'Clip editor'}</h1></div><div class="header-actions"><button onclick={saveProject} disabled={!info}>Save edits</button><label>Export <select bind:value={fps}><option value="60">60 fps</option><option value="120">120 fps</option><option value="240">240 fps</option><option value="480">480 fps</option><option value="960">960 fps</option><option value="custom">Custom</option></select></label>{#if fps === 'custom'}<input aria-label="Custom export FPS" type="number" min="1" max="2147483647" step="1" bind:value={customFps}/>{/if}<button class="export" disabled={!info || !validFps || !!$exportStarted} onclick={requestExport}>{$exportStarted ? 'Exporting…' : 'Export'}</button></div></div>
{#if loading}<p class="notice">Preparing source preview and audio stems…</p>
{:else if loadError}<p class="notice error">{loadError}</p>
{:else if info}
  <div class="meta">{info.width}×{info.height} · source {tc(info.duration)} · {info.video_fps.toFixed(2)} fps</div>
  <section class="workbench">
    <div class="preview"><video bind:this={video} src={convertFileSrc(info.path)} muted playsinline ontimeupdate={onVideoTime} onended={pause}></video><div class="transport"><button onclick={togglePlay}>{playing ? 'Pause' : 'Play'}</button><output>{tc(sourceTime)}</output><span>edited {sourceToEdited(plan.ranges, sourceTime) === null ? 'gap' : tc(sourceToEdited(plan.ranges, sourceTime) ?? 0)} / {tc(totalDuration)}</span></div></div>
    <aside class="inspector"><h2>Audio tracks</h2>{#if info.audio.length}{#each info.audio as track, index (track.stream_index)}{@const setting = trackSetting(track.stream_index)}<div class="track"><div><b>{track.name && track.name.toLowerCase() !== 'und' ? track.name : `Audio ${index + 1}`}</b><small>{track.channels} ch · {track.sample_rate} Hz</small></div><label>gain <input aria-label={`Gain for ${track.name}`} type="range" min="-60" max="12" step="0.5" value={setting.gain_db} oninput={(e) => alterAudio(track.stream_index, { gain_db: Number(e.currentTarget.value) })}/><output>{setting.gain_db.toFixed(1)} dB</output></label><button class:muted={setting.muted} onclick={() => alterAudio(track.stream_index, { muted: !setting.muted })}>{setting.muted ? 'Unmute' : 'Mute'}</button><audio bind:this={stemElements[index]} src={convertFileSrc(track.preview_path)} preload="auto"></audio></div>{/each}{:else}<p class="quiet">No audio tracks in this clip.</p>{/if}</aside>
  </section>
  <section class="timeline-panel"><div class="timeline-head"><h2>Source timeline</h2><span>Source time · removed sections close during preview</span></div><div class="ruler">{#each rulerTicks as tick}<span style={`left:${percent(tick)}`}>{tc(tick)}</span>{/each}</div><div class="timeline" bind:this={timeline} role="slider" aria-label="Source timeline" aria-valuemin={0} aria-valuemax={info.duration} aria-valuenow={sourceTime} tabindex="0" onclick={timelineClick} onkeydown={(e) => { if(e.key === 'ArrowLeft') seek(sourceTime - 1); if(e.key === 'ArrowRight') seek(sourceTime + 1); }}>{#each plan.ranges as range, index}<button class:selected={selected === index} class="range" style={`left:${percent(range.start)};width:${percent(range.end - range.start)}`} onclick={(event) => { selected = index; timelineClick(event); event.stopPropagation(); }}><span>{tc(range.start)} — {tc(range.end)}</span></button>{/each}<i class="playhead" style={`left:${percent(sourceTime)}`}></i></div><div class="waveforms">{#each info.audio as track, index (track.stream_index)}<div class="wave-lane"><span>{track.name && track.name.toLowerCase() !== 'und' ? track.name : `Audio ${index + 1}`}</span><svg viewBox="0 0 1024 48" preserveAspectRatio="none" aria-label={`${track.name} waveform`}><polyline points={track.waveform.map((peak, x) => `${x},${24 - clamp(peak, -1, 1) * 22}`).join(' ')} /></svg></div>{/each}</div><div class="timecode"><span>source {tc(sourceTime)}</span><span>selected {current() ? `${tc(current()!.start)} — ${tc(current()!.end)}` : 'none'}</span><span>output {tc(totalDuration)}</span></div></section>
  <div class="controls"><button onclick={() => trim('start')}>Set in <kbd>I</kbd></button><button onclick={() => trim('end')}>Set out <kbd>O</kbd></button><button onclick={split}>Split <kbd>C</kbd></button><button onclick={remove} disabled={plan.ranges.length <= 1}>Delete</button><span class="divider"></span><button onclick={undo} disabled={!canUndo}>Undo</button><button onclick={redo} disabled={!canRedo}>Redo</button><button onclick={reset}>Reset</button></div>
  {#if error}<p class="notice error">{error}</p>{/if}{#if saved}<p class="notice ok" title={saved}>Edits saved.</p>{/if}{#if $exportError}<p class="notice error">Export failed: {$exportError}</p>{/if}{#if $lastExported?.source === info.path}<p class="notice ok">Exported {tc($lastExported.seconds)} at {$lastExported.fps} fps.</p>{/if}
{/if}

<style>
  :global(*){box-sizing:border-box}
  .editor-head{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:36px;padding-bottom:8px;border-bottom:1px solid var(--line)}
  .crumb{display:flex;align-items:center;gap:7px;min-width:0}.editor-head a,.editor-head span{color:var(--muted);font:12px/16px "Segoe UI",system-ui,sans-serif;text-decoration:none}.editor-head h1{min-width:0;margin:0;overflow:hidden;color:var(--text);font:650 18px/24px Bahnschrift,"Segoe UI Variable",sans-serif;text-overflow:ellipsis;white-space:nowrap}
  .header-actions,.transport,.controls,.timecode,.timeline-head{display:flex;align-items:center;gap:8px}.header-actions{flex:none}.header-actions label{display:flex;align-items:center;gap:5px;color:var(--muted);font:12px/16px "Segoe UI",system-ui,sans-serif}
  button,select,input{border:1px solid var(--line);border-radius:var(--r4);background:var(--raised);color:var(--text);font:12px/16px "Segoe UI",system-ui,sans-serif}button{padding:6px 8px;cursor:pointer}select,input{padding:5px 7px}button:hover:not(:disabled){border-color:var(--steel);background:#2b3542}button:disabled{opacity:.5;cursor:not-allowed}button:focus-visible,select:focus-visible,input:focus-visible,.timeline:focus-visible{outline:2px solid var(--steel);outline-offset:2px}.export{border-color:#719bc8;background:#496f99;font-weight:600}
  .meta,.quiet,.timeline-head span{color:var(--muted);font:11px/16px "Segoe UI",system-ui,sans-serif}.meta{margin:6px 0 0}.workbench{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:12px;margin-top:8px}.preview,.inspector,.timeline-panel{border:1px solid var(--line);border-radius:var(--r8);background:var(--panel)}
  .preview{min-width:0}.preview video{display:block;width:100%;height:clamp(130px,calc(100vh - 410px),240px);min-height:130px;background:#0d1014;object-fit:contain}.transport{min-height:34px;padding:4px 8px;border-top:1px solid var(--line)}.transport output,.timecode{font-variant-numeric:tabular-nums}.transport span{margin-left:auto;color:var(--muted);font:11px/16px "Segoe UI",system-ui,sans-serif}
  .inspector{padding:0}.inspector h2{margin:0;padding:8px 10px;border-bottom:1px solid var(--line);font:600 13px/18px Bahnschrift,"Segoe UI Variable",sans-serif}.track{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 8px;padding:7px 10px;border-bottom:1px solid var(--line)}.track:last-child{border-bottom:0}.track>div{grid-column:1;min-width:0;line-height:16px}.track b{font:600 12px/16px "Segoe UI",system-ui,sans-serif}.track small{display:block;color:var(--muted);font:10px/14px "Segoe UI",system-ui,sans-serif}.track label{grid-column:1 / -1;grid-row:2;display:flex;align-items:center;gap:6px;font:11px/16px "Segoe UI",system-ui,sans-serif}.track input{flex:1;padding:0}.track output{width:54px;text-align:right;font-variant-numeric:tabular-nums}.track button{grid-column:2;grid-row:1;align-self:center;width:max-content}.muted{border-color:#8b7241;color:var(--amber)}
  .timeline-panel{margin-top:10px;padding:0}.timeline-head{justify-content:space-between;padding:7px 10px;border-bottom:1px solid var(--line)}.timeline-head h2{margin:0;font:600 13px/18px Bahnschrift,"Segoe UI Variable",sans-serif}.ruler{position:relative;height:18px;margin:0 10px;color:var(--muted);font:10px/18px "Segoe UI",system-ui,sans-serif;font-variant-numeric:tabular-nums}.ruler span{position:absolute;transform:translateX(-50%)}.ruler span:first-child{transform:none}.ruler span:last-child{transform:translateX(-100%)}
  .timeline{position:relative;height:38px;margin:0 10px;outline:none;background:#12161b;cursor:crosshair}.range{position:absolute;top:7px;bottom:7px;min-width:2px;overflow:hidden;border:1px solid var(--steel);border-radius:2px;background:#405d7a;color:var(--text);font:10px/22px "Segoe UI",system-ui,sans-serif;text-align:left;white-space:nowrap}.range.selected{border-color:var(--amber);background:#5e5039;color:#fff1cf}.range span{padding:0 5px}.playhead{position:absolute;top:0;bottom:0;border-left:2px solid var(--text);pointer-events:none}.waveforms{display:grid;gap:3px;margin:6px 10px 0}.wave-lane{position:relative;height:22px;background:#12161b}.wave-lane>span{position:absolute;z-index:1;top:0;left:0;width:54px;overflow:hidden;padding:4px 6px;color:var(--muted);background:#12161b;font:10px/14px "Segoe UI",system-ui,sans-serif;text-overflow:ellipsis;white-space:nowrap}.waveforms svg{display:block;width:100%;height:22px}.waveforms polyline{fill:none;stroke:var(--steel);stroke-width:1}.timecode{justify-content:space-between;margin-top:6px;padding:6px 10px;border-top:1px solid var(--line);color:var(--muted);font:11px/16px "Segoe UI",system-ui,sans-serif}
  .controls{min-height:42px;flex-wrap:wrap;padding-top:8px}.divider{height:20px;margin:0 2px;border-left:1px solid var(--line)}.notice{margin:8px 0;padding:7px 9px;border-left:3px solid var(--steel);background:var(--panel);font:12px/16px "Segoe UI",system-ui,sans-serif}.notice.error{border-color:var(--coral);background:#32191d}.notice.ok{border-color:var(--mint);background:#14291e}kbd{color:var(--muted);font:11px/16px "Segoe UI",system-ui,sans-serif}
  @media(max-width:760px){.workbench{grid-template-columns:1fr}.preview video{height:min(32vh,220px)}.inspector{order:2}.transport{flex-wrap:wrap}.transport span{margin-left:0}.timeline-head{align-items:flex-start;flex-direction:column}.timecode{gap:6px;font-size:10px}}@media(max-width:620px){.editor-head{align-items:flex-start;flex-direction:column}.header-actions{width:100%;flex-wrap:wrap}.header-actions button:first-child,.header-actions label{display:none}.header-actions input{width:72px}.timeline-head span{display:none}.timecode span:nth-child(2){display:none}}
</style>
